const p = $json.body || {};
const { playlistId, userId, prompt, size, genres, mood, language, catalogSample, callbackUrl, callbackSecret } = p;
if (!Number.isInteger(playlistId) || playlistId <= 0) throw new Error(`playlistId inválido: ${playlistId}`);
if (!Number.isInteger(userId) || userId <= 0) throw new Error(`userId inválido: ${userId}`);
if (!prompt || typeof prompt !== 'string' || prompt.length < 3) throw new Error('prompt vacío');
if (!callbackUrl || !/^https?:\/\//.test(callbackUrl)) throw new Error(`callbackUrl inválido: ${callbackUrl}`);
if (!Array.isArray(catalogSample) || catalogSample.length === 0) throw new Error('catalogSample vacío');
const safeSample = catalogSample.filter(b => Number.isInteger(b?.id) && typeof b?.title === 'string').slice(0, 80);
const targetSize = Number.isInteger(size) ? Math.max(3, Math.min(25, size)) : 8;
const genreStr = Array.isArray(genres) && genres.length ? genres.slice(0,10).join(', ') : 'no especificados';
const moodStr = typeof mood === 'string' && mood ? mood.slice(0,80) : 'no especificado';
const lang = typeof language === 'string' ? language.slice(0,10) : 'es';
const sampleList = safeSample.map(b => `- [${b.id}] ${b.title}${b.author ? ' — '+b.author : ''}`).join('\n');
const agentInput = `Genera una playlist de lectura para la siguiente petición.\n\nPETICIÓN: "${prompt.trim()}"\nGéneros preferidos: ${genreStr}\nVibra/mood: ${moodStr}\nTamaño deseado: ${targetSize} libros\nIdioma respuesta: ${lang}\n\nCATÁLOGO EXISTENTE (IDs confirmados — úsalos si encajan):\n${sampleList}\n\nplaylistId: ${playlistId}`;
return { playlistId, userId, prompt: prompt.trim(), size: targetSize, genres: Array.isArray(genres)?genres.slice(0,10):[], mood: moodStr, language: lang, catalogSample: safeSample, callbackUrl, callbackSecret: callbackSecret||null, agentInput, startTime: Date.now() };

const prev = $('Validar Payload').item.json;
const out = $input.item.json.output || '';
let parsed = null;
try { let c = out.trim(); if(c.startsWith('```')) c=c.replace(/^```(?:json)?\n?/,'').replace(/\n?```$/,'').trim(); parsed=JSON.parse(c); } catch { return { ...prev, aiStatus:'error', aiErrorMessage:'JSON inválido: '+out.slice(0,200), aiTitle:null, aiDescription:null, aiItems:[] }; }
if (!parsed || parsed.status==='error') return { ...prev, aiStatus:'error', aiErrorMessage: parsed?.errorMessage||'El agente reportó error', aiTitle:null, aiDescription:null, aiItems:[] };
const items=[];
const seen=new Set();
for (const it of (parsed.items||[])) { const id=Number(it?.catalogBookId); if(!Number.isInteger(id)||id<=0||seen.has(id)) continue; seen.add(id); items.push({catalogBookId:id,position:items.length+1,note:it.note||null}); if(items.length>=prev.size) break; }
if (items.length===0) return { ...prev, aiStatus:'error', aiErrorMessage:'Sin items válidos', aiTitle:null, aiDescription:null, aiItems:[] };
return { ...prev, aiStatus:'success', aiErrorMessage:null, aiTitle: typeof parsed.title==='string'?parsed.title.slice(0,100):null, aiDescription: typeof parsed.description==='string'?parsed.description.slice(0,2000):null, aiItems:items, processingTime: Date.now()-(prev.startTime||Date.now()) };

const d = $input.item.json;
const parts = [
  'book collection cover art',
  d.aiTitle || d.prompt.slice(0, 80),
  Array.isArray(d.genres) && d.genres.length > 0 ? d.genres.slice(0, 3).join(' ') : '',
  d.mood && d.mood !== 'no especificado' ? d.mood : '',
  'stylized vibrant painterly minimalist no text no letters'
].filter(Boolean);
const coverPrompt = parts.join(', ').slice(0, 300);
let fallbackCover = null;
if (Array.isArray(d.aiItems) && d.aiItems.length > 0 && Array.isArray(d.catalogSample)) {
  const coverMap = new Map(d.catalogSample.map(b => [b.id, b.coverUrl || null]));
  for (const item of d.aiItems) {
    const cover = coverMap.get(item.catalogBookId);
    if (cover) { fallbackCover = cover; break; }
  }
}
// URL de Pollinations: Cloudinary la descarga desde sus propios servidores
const shortPrompt = coverPrompt.slice(0, 150);
const seed = Math.abs(shortPrompt.split('').reduce((a, c) => (a << 5) - a + c.charCodeAt(0), 0)) % 9999;
const pollinationsUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(shortPrompt) + '?width=512&height=512&model=flux&nologo=true&seed=' + seed;
return { ...d, coverPrompt, fallbackCover, pollinationsUrl };

const prev = $('Preparar Prompt Portada').item.json;
const binData = $input.item.binary;
const resp = $input.item.json;

// 1) Respuesta binaria (HuggingFace)
if (binData && binData.data && binData.data.data) {
  const mimeType = binData.data.mimeType || 'image/png';
  return { ...prev, uploadFile: 'data:' + mimeType + ';base64,' + binData.data.data, directUrl: null };
}

// 2) Respuesta JSON OpenAI-compatible (Together AI, etc.)
if (resp && !resp.error && Array.isArray(resp.data) && resp.data[0]) {
  const imgData = resp.data[0];
  if (imgData.url && !imgData.b64_json) return { ...prev, uploadFile: imgData.url, directUrl: imgData.url };
  if (imgData.b64_json) return { ...prev, uploadFile: 'data:image/png;base64,' + imgData.b64_json, directUrl: null };
}

// 3) Fallback: URL de Pollinations — Cloudinary la descarga desde sus servidores
if (prev.pollinationsUrl) {
  return { ...prev, uploadFile: prev.pollinationsUrl, directUrl: prev.pollinationsUrl };
}

return { ...prev, uploadFile: null, directUrl: null };

const prev = $('Procesar Imagen').item.json;
const cloudResp = $input.item.json;
const aiCoverUrl = cloudResp.secure_url || prev.directUrl || prev.fallbackCover || null;
const { uploadFile, directUrl, coverPrompt, fallbackCover, ...cleanPrev } = prev;
return { ...cleanPrev, aiCoverUrl };

const prev = $('Validar Payload').item.json;
const err = $json.error || $json;
return { ...prev, aiStatus:'error', aiErrorMessage:(err?.message||'Error en generación IA').slice(0,500), aiTitle:null, aiDescription:null, aiCoverUrl:null, aiItems:[] };
